import{_ as a,o as t,c as o,a6 as i}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Adapt practical automation recipes","description":"","frontmatter":{"title":"Adapt practical automation recipes","docId":"user.automations.recipes","translationKey":"user.automations.recipes","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"43a103ef68e43d691eec2214ffefb5e2e0e6b663afa9f4e63b5dac0ccec162ea","translationRevision":"43a103ef68e43d691eec2214ffefb5e2e0e6b663afa9f4e63b5dac0ccec162ea","order":30},"headers":[],"relativePath":"en/user/automations/recipes.md","filePath":"en/user/automations/recipes.md","lastUpdated":1794591482000}'),n={name:"en/user/automations/recipes.md"};function r(c,e,s,d,l,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adapt-practical-automation-recipes" tabindex="-1">Adapt practical automation recipes <a class="header-anchor" href="#adapt-practical-automation-recipes" aria-label="Permalink to &quot;Adapt practical automation recipes {#adapt-practical-automation-recipes}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Turn a working <a href="./first-rule.html">logging rule</a> into narrowly matched reactions. You need an active profile and observed event fields. Begin with <code>core.log</code> actions; replace them with another effect only after confirming matching and frequency.</p><h2 id="match-a-chat-command" tabindex="-1">Match a chat command <a class="header-anchor" href="#match-a-chat-command" aria-label="Permalink to &quot;Match a chat command {#match-a-chat-command}&quot;">​</a></h2><p>Create a <code>tiktok.chat</code> event with <code>event.data.comment</code> equals (<code>eq</code>) <code>!hello</code>. Log:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello {{ event.user.uniqueId }}</span></span></code></pre></div><p>Use a per-user cooldown of <code>30</code> seconds so one viewer cannot continually trigger it while another viewer still has an independent opportunity. Exact equality is useful for a command; contains matching also accepts messages with surrounding text. Choose deliberately.</p><h2 id="record-a-qualifying-gift" tabindex="-1">Record a qualifying gift <a class="header-anchor" href="#record-a-qualifying-gift" aria-label="Permalink to &quot;Record a qualifying gift {#record-a-qualifying-gift}&quot;">​</a></h2><p>Create a <code>tiktok.gift</code> event with <code>event.data.diamondCount</code> greater than or equal (<code>gte</code>) <code>10</code>. Log:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Gift {{ event.data.giftName }} from {{ event.user.uniqueId }}</span></span></code></pre></div><p>Inspect actual gift details first. A gift&#39;s diamond value, repeat count and completion flag are different fields. If you require a completion-only reaction, check that the incoming payload supplies <code>event.data.repeatEnd</code>, then use the boolean true condition. Do not infer one execution per completed combo from a name filter alone.</p><h2 id="bound-a-shared-reaction" tabindex="-1">Bound a shared reaction <a class="header-anchor" href="#bound-a-shared-reaction" aria-label="Permalink to &quot;Bound a shared reaction {#bound-a-shared-reaction}&quot;">​</a></h2><p>Create a <code>tiktok.follow</code> event with a global cooldown of <code>10</code> seconds. Link a short log action. If two viewers follow during that interval, the global cooldown can suppress the later reaction. Use per-user scope instead when each viewer needs a separate allowance.</p><p>For multiple actions, order the list and keep all-actions mode when each step is required. Random mode chooses an action; it does not execute every step in random order. Add <code>core.delay</code> only when later steps should wait.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>These triggers, field filters and cooldown controls are available in the local engine. A run should correspond to an accepted matching event, subject to cooldown and enabled state. Provider-specific acceptance still needs your actual LIVE check.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>If a recipe fails, return to a single log action, inspect the payload and temporarily simplify conditions. Do not disable limits on a busy stream while investigating. Audio, points, HTTP and plugin tests can perform real effects. Check <a href="./../plugins/audio.html">audio setup</a>, <a href="./variables.html">variables</a> and <a href="./../preferences/troubleshooting.html">run diagnostics</a> before adding those dependencies.</p>',18)])])}const f=a(n,[["render",r]]);export{h as __pageData,f as default};
